"""RoboPaint trajectory and calibration. Uses only the public robot client and camera observations."""
import sys,json,time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=Path('/app/output'); RUNS=Path('/app/runs')
Q=[0.,1.,0.,0.]
ZP=.0202
S=.227185/1024

def world(u,v,z=ZP):
    return np.array([-.1+(512-v)*S,(512-u)*S,z])

class Painter:
    def __init__(self):
        self.r=Robot(); self.obs=self.r.get_obs(cameras=[])
        self.p=np.array(self.obs.meta['proprio']['now'][7:10])
    def send(self,pts,label='move',cams=('practice_cam',)):
        pts=np.asarray(pts); poses=np.c_[pts,np.tile(Q,(len(pts),1))]
        for start in range(0,len(pts),180):
            chunk=poses[start:start+180]
            status=self.r.status()
            try:
                res=self.r.submit('ee_pose',chunk,dt=.05,cameras=list(cams),video='none',note=label)
            except Exception:
                state=self.r.wait_ready()
                print('RECOVERY',state,flush=True)
                raise
            ix=res.meta['calls']; res.save(RUNS/f'{ix:04d}_{label}')
            for cam,a in res.last.items():Image.fromarray(a).save(ROOT/f'{cam}.png')
            self.p=np.array(res.meta['proprio']['now'][7:10])
            with (ROOT/'executed.jsonl').open('a') as f:f.write(json.dumps({'call':ix,'label':label,'poses':chunk.tolist(),'meta':res.meta})+'\n')
            print(label,ix,'tip',self.p,'steps',res.meta.get('control_steps_chunk'),'plan',res.meta.get('plan'),'left',res.meta.get('time_left_s'),flush=True)
            if res.stopped:raise RuntimeError('Partial execution')
        return res
    def move(self,p,seconds=1,label='move',cams=('practice_cam',)):
        pts=np.linspace(self.p,p,max(2,round(seconds*20))+1)[1:]
        return self.send(pts,label,cams)
    def hold(self,seconds=.3,label='hold'):
        return self.send(np.tile(self.p,(round(seconds*20),1)),label)
    def observe(self,label='observe'):
        o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True)
        o.save(RUNS/label)
        for cam,a in o.last.items():Image.fromarray(a).save(ROOT/f'{cam}.png')
        return o
    def dip(self):
        self.move([self.p[0],self.p[1],.08],.7,'lift')
        self.move([-.1,.1856,.08],2,'ink_approach')
        self.move([-.1,.1856,.023],1,'dip')
        self.hold(.5)
        self.move([-.1,.1856,.08],1,'ink_lift')

if __name__=='__main__':
    p=Painter()
    if sys.argv[1]=='clear':
        p.move([-.1,.1856,.10],2,'clear',('scene_cam','canvas_cam','side_cam'))
        p.observe('cleared')
