"""Image-only coverage planner for four connected brush contacts."""
import numpy as np
from PIL import Image,ImageDraw
from scipy import ndimage as ndi
from collections import defaultdict
from pathlib import Path
S=.227185/1024
im=np.array(Image.open('/app/target.png')); target=im[:,:,0]<100
Y,X=np.mgrid[:1024,:1024]
def poly(points):
 a=Image.new('1',(1024,1024));ImageDraw.Draw(a).polygon(points,fill=1);return np.array(a)
# Each region is clipped to the visible ink in the exemplar. Overlaps keep joins solid.
m1=target & poly([(370,245),(675,245),(675,313),(520,320),(480,330),(450,335),(370,335)])
m2=target & poly([(280,480),(465,454),(665,415),(740,430),(742,475),(545,478),(457,491),(345,518),(280,518)])
m3=target & poly([(448,310),(535,320),(530,421),(516,456),(505,490),(496,545),(475,610),(447,658),(417,688),(345,726),(250,744),(245,707),(350,650),(410,575),(441,512),(463,451),(471,365)])
m4=target & poly([(489,461),(512,463),(600,575),(662,640),(815,737),(815,760),(645,760),(562,641),(495,512)])
# Assign any missed pixels to the nearest region; overlap the internal joins by 1 mm.
regions=[m1,m2,m3,m4]
missing=target & ~np.logical_or.reduce(regions)
dist=np.array([ndi.distance_transform_edt(~m) for m in regions]); lab=dist.argmin(axis=0)
for i in range(4):regions[i] |= missing & (lab==i)
colors=np.array([[180,40,50],[40,110,180],[40,150,70],[145,65,175]])
a=im.copy()
for m,c in zip(regions,colors):a[m]=c
Image.fromarray(a).save('/app/output/regions.png')

def boundaries(mask):
 # Trace exposed pixel-cell edges, clockwise around each component.
 edges=defaultdict(list)
 up=mask & ~np.roll(mask,1,axis=0);dn=mask & ~np.roll(mask,-1,axis=0)
 le=mask & ~np.roll(mask,1,axis=1);ri=mask & ~np.roll(mask,-1,axis=1)
 for y,x in np.argwhere(up):edges[(x-.5,y-.5)].append((x+.5,y-.5))
 for y,x in np.argwhere(ri):edges[(x+.5,y-.5)].append((x+.5,y+.5))
 for y,x in np.argwhere(dn):edges[(x+.5,y+.5)].append((x-.5,y+.5))
 for y,x in np.argwhere(le):edges[(x-.5,y+.5)].append((x-.5,y-.5))
 out=[]
 while edges:
  st=next(iter(edges));pt=st;path=[]
  while True:
   path.append(pt);nxt=edges[pt].pop()
   if not edges[pt]:del edges[pt]
   pt=nxt
   if pt==st:break
  if len(path)>8:
   a=np.asarray(path);a=ndi.gaussian_filter1d(a,1.5,axis=0,mode='wrap');out.append(a)
 return out

def sample_line(a,b,step=.45):
 return np.linspace(a,b,max(2,int(np.linalg.norm(b-a)/step)+1))[1:]

def plan(mask):
 d=ndi.distance_transform_edt(mask)
 loops=[]
 for r in np.arange(4.0,d.max(),5.):
  for loop in boundaries(d>=r):loops.append((r,loop))
 # Start in the innermost, broad part to keep the initial gathered-hair blot inside.
 loops.sort(key=lambda x:-x[0])
 path=[];prev=None
 for r,loop in loops:
  if prev is None: idx=0
  else:idx=np.linalg.norm(loop-prev,axis=1).argmin()
  loop=np.roll(loop,-idx,axis=0);loop=np.vstack([loop,loop[0]])
  if prev is not None:
   # For these simply connected stroke regions the nested contours have short joins.
   join=sample_line(prev,loop[0]);
   good=d[np.clip(np.round(join[:,1]).astype(int),0,1023),np.clip(np.round(join[:,0]).astype(int),0,1023)]
   if good.min()<3: print('JOIN_NEEDS_ROUTING',r,good.min())
   path.extend(join)
  for a,b in zip(loop[:-1],loop[1:]):path.extend(sample_line(a,b))
  prev=loop[-1]
 return np.array(path)
if __name__=='__main__':
 for i,m in enumerate(regions):
  np.save(f'/app/output/mask{i+1}.npy',m)
  p=plan(m);np.save(f'/app/output/path{i+1}.npy',p)
  length=np.linalg.norm(np.diff(p,axis=0),axis=1).sum()*S*1000
  print(i+1,m.sum(),len(p),'lengthmm',length)
