from execute_path import *
def refined_trajectory(uvd):
 xyz=np.array([world(u,v,ZP-d) for u,v,d in uvd])
 ds=np.linalg.norm(np.diff(xyz,axis=0),axis=1);speed=np.where(uvd[1:,2]<.002,.0015,.002)
